SELECT pp.id, pp.code, pp.create_user_id AS createUserId, pp.create_user_name AS createUserName, pp.create_time AS createTime, pp.supplier_id, (SELECT name FROM supplier WHERE id=pp.supplier_id) AS supplierName, ppd.sku_id, ppd.sku_no, ppd.product_name,ppd.min_qty,ppd.max_qty, pp.approve_status, ppd.tax_price, ppd.currency, ppd.tax_rate*100 AS taxRate , ppd.effective_date, pp.purchase_org_id, pp.purchase_org_name, ppd.id AS purchasePriceDetailId, ppd.disabled FROM purchase_price_detail ppd INNER JOIN purchase_price pp ON ppd.purchase_price_id=pp.id WHERE pp.is_deleted=false AND ppd.is_deleted= false
AND ppd.sku_id IN
#{skuId}
AND pp.supplier_id IN (SELECT id FROM supplier WHERE is_deleted= false AND name LIKE '%${params.name}%')
AND pp.purchase_org_id IN
#{purchaseOrgId}
AND pp.approve_status IN
#{approveStatus}
AND ppd.effective_date >= #{params.effectiveDateList[0]} and (#{params.effectiveDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > ppd.effective_date
AND ppd.expire_date >= #{params.expireDateList[0]} and (#{params.expireDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > ppd.expire_date
AND pp.create_time >= #{params.createTimeList[0]} and (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > pp.create_time
AND pp.create_user_id IN
#{createUserId}
AND ppd.product_name LIKE concat('%', #{params.productName} ,'%')
AND pp.approve_status IN
#{approveStatus}
#{params.param}
ORDER BY
${item.field} ${item.sort}
pp.create_time DESC,ppd.id DESC

SELECT pp.id, pp.code, pp.create_user_id AS createUserId, pp.create_user_name AS createUserName, pp.create_time, pp.supplier_id, (SELECT name FROM supplier WHERE id=pp.supplier_id) AS supplierName, ppd.sku_id, ppd.sku_no, ppd.product_name,ppd.min_qty,ppd.max_qty, pp.approve_status, ppd.tax_price, ppd.tax_rate*100 AS taxRate , ppd.effective_date, ppd.currency, pp.purchase_org_id, pp.purchase_org_name FROM purchase_price_detail ppd LEFT JOIN purchase_price pp ON ppd.purchase_price_id=pp.id WHERE pp.is_deleted=false AND ppd.is_deleted= false
AND pp.id IN
#{id}
AND ppd.sku_id IN
#{skuId}
AND pp.supplier_id IN (SELECT id FROM supplier WHERE is_deleted= false AND name LIKE '%${params.name}%')
AND pp.purchase_org_id IN
#{purchaseOrgId}
AND pp.approve_status IN
#{approveStatus}
AND ppd.effective_date between #{params.effectiveDateList[0]} and #{params.effectiveDateList[1]}
AND ppd.expire_date between #{params.expireDateList[0]} and #{params.expireDateList[1]}
AND pp.expire_date between #{params.createTimeList[0]} and #{params.createTimeList[1]}
AND pp.create_user_id IN
#{createUserId}
AND ppd.name LIKE concat('%', #{params.productName} ,'%')
